\coordinate (E1) at (6,3.6);
\coordinate (E2) at (6,2);
\coordinate (E3) at (6,0.8);
\coordinate (E4) at (6,-0.8);
\coordinate (E5) at (6,-2);
\coordinate (E6) at (6,-3.6);
\draw (O)--(J1) node[midway,above] {$\frac13$};
\draw (O)--(J2) node[midway,above] {$\frac13$};
\draw (O)--(J3) node[midway,below] {$\frac13$};
\draw (J1)--(E1) node[midway,above] {$\frac16$};
\draw (J1)--(E2) node[midway,below] {$\frac56$};
\draw (J2)--(E3) node[midway,above] {$\frac26$};
\draw (J2)--(E4) node[midway,below] {$\frac46$};
\draw (J3)--(E5) node[midway,above] {$\frac36$};
\draw (J3)--(E6) node[midway,below] {$\frac36$};
\path (O) node[left] {Start};
\path (J1) node[fill=white] {$J_1$};
\path (J2) node[fill=white] {$J_2$};
\path (J3) node[fill=white] {$J_3$};
\path (E1) node[right] {$S$};
\path (E2) node[right] {$S'$};
\path (E3) node[right] {$S$};
\path (E4) node[right] {$S'$};
\path (E5) node[right] {$S$};
\path (E6) node[right] {$S'$};
